<div class="card card-body"><form method="POST" action="<?php echo e($action); ?>" enctype="multipart/form-data"><?php echo csrf_field(); ?> <?php if($method!=='POST'): ?> <?php echo method_field($method); ?> <?php endif; ?>
<div class="row g-3"><div class="col-md-6"><label class="form-label">Asset name</label><input required class="form-control" name="asset_name" value="<?php echo e(old('asset_name',$siteAsset->asset_name ?? '')); ?>"></div><div class="col-md-3"><label class="form-label">Asset code</label><input required class="form-control" name="asset_code" value="<?php echo e(old('asset_code',$siteAsset->asset_code ?? '')); ?>"></div><div class="col-md-3"><label class="form-label">Category</label><input required class="form-control" name="category" value="<?php echo e(old('category',$siteAsset->category ?? '')); ?>"></div><div class="col-md-6"><label class="form-label">Work site</label><select class="form-select" name="work_site_id"><option value="">Unassigned</option><?php $__currentLoopData = $sites; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $site): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($site->id); ?>" <?php if(old('work_site_id',$siteAsset->work_site_id ?? '')==$site->id): echo 'selected'; endif; ?>><?php echo e($site->site_name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-md-3"><label class="form-label">Current meter</label><input required type="number" step="0.01" min="0" class="form-control" name="current_meter" value="<?php echo e(old('current_meter',$siteAsset->current_meter ?? 0)); ?>"></div><div class="col-md-3"><label class="form-label">Meter unit</label><select class="form-select" name="meter_unit"><option value="hours" <?php if(old('meter_unit',$siteAsset->meter_unit ?? 'hours')==='hours'): echo 'selected'; endif; ?>>Hours</option><option value="kilometres" <?php if(old('meter_unit',$siteAsset->meter_unit ?? '')==='kilometres'): echo 'selected'; endif; ?>>Kilometres</option></select></div><div class="col-md-4"><label class="form-label">Brand</label><input class="form-control" name="brand" value="<?php echo e(old('brand',$siteAsset->brand ?? '')); ?>"></div><div class="col-md-4"><label class="form-label">Model</label><input class="form-control" name="model" value="<?php echo e(old('model',$siteAsset->model ?? '')); ?>"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php $__currentLoopData = ['available','working','maintenance','breakdown','inactive']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $status): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($status); ?>" <?php if(old('status',$siteAsset->status ?? 'available')===$status): echo 'selected'; endif; ?>><?php echo e(ucfirst($status)); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-md-6"><label class="form-label">Image</label><input type="file" class="form-control" name="image" accept="image/*"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="4" name="description"><?php echo e(old('description',$siteAsset->description ?? '')); ?></textarea></div></div><div class="mt-4"><a class="btn btn-outline-light" href="<?php echo e(route('admin.site-assets')); ?>">Cancel</a><button class="btn btn-primary">Save Asset</button></div></form></div>
